content.text:
@import "tailwindcss";
@import "tw-animate-css";

:root {
  color-scheme: light;
  --background: #fafafa;
  --foreground: #171717;
  --card: #ffffff;
  --muted: #f3f3f3;
  --muted-foreground: #626262;
  --border: #e5e5e5;
  --ring: #0070f3;
  --warn: #92400e;
  --warn-surface: #fff8ed;
}

@theme inline {
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-border: var(--border);
  --color-ring: var(--ring);
}

@layer base {
  * {
    border-color: var(--border);
  }
  body {
    margin: 0;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }
  button,
  input,
  summary {
    font: inherit;
  }
  button,
  summary {
    cursor: pointer;
  }
  button {
    color: inherit;
  }
  a {
    text-underline-offset: 3px;
  }
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 4px;
  }
}

.ranking-page {
  max-width: 1160px;
  margin: 0 auto;
  padding: 56px 32px 80px;
}
.eyebrow {
  font-size: 11px;
  letter-spacing: 0.15em;
  font-weight: 650;
  color: var(--muted-foreground);
}
.ranking-header h1 {
  margin: 14px 0 12px;
  font-size: clamp(30px, 4vw, 44px);
  font-weight: 620;
  line-height: 1.1;
  letter-spacing: -0.045em;
}
.scope {
  font-size: 14px;
  color: var(--muted-foreground);
}
.scope span {
  padding: 0 7px;
}
.snapshot-line {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  margin-top: 18px;
  font-size: 12px;
  color: var(--muted-foreground);
}
.method {
  margin: 18px 0 34px;
  font-size: 13px;
}
.method summary {
  width: fit-content;
  color: var(--muted-foreground);
}
.method > div {
  max-width: 760px;
  padding: 8px 0 2px;
  color: var(--muted-foreground);
  line-height: 1.7;
}
.method p + p {
  margin-top: 10px;
}
.method strong {
  font-weight: 600;
  color: var(--foreground);
}
.table-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.status-filters {
  display: flex;
  align-items: center;
  gap: 4px;
}
.status-filters button {
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 13px;
  color: var(--muted-foreground);
}
.status-filters button:hover {
  background: var(--muted);
}
.status-filters button[aria-pressed="true"] {
  background: var(--foreground);
  color: white;
}
.status-filters button span {
  margin-left: 5px;
  font-size: 11px;
  font-variant-numeric: tabular-nums;
}
.restaurant-search {
  display: flex;
  align-items: center;
  gap: 8px;
  width: 240px;
  border: 1px solid #8a8a8a;
  padding: 8px 10px;
  border-radius: 6px;
  background: var(--card);
  color: var(--muted-foreground);
}
.restaurant-search:focus-within {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.restaurant-search input {
  min-width: 0;
  width: 100%;
  font-size: 13px;
  outline: none;
  color: var(--foreground);
  background: transparent;
}
.restaurant-search input::placeholder {
  color: var(--muted-foreground);
}
.group-note {
  margin: 0 0 14px;
  max-width: 780px;
  font-size: 13px;
  color: var(--muted-foreground);
  line-height: 1.6;
}
.ranking-table-wrap {
  border: 1px solid var(--border);
  border-radius: 10px;
  background: var(--card);
  overflow: hidden;
}
.ranking-table {
  width: 100%;
  border-collapse: collapse;
  text-align: left;
  font-size: 14px;
}
.ranking-table th {
  padding: 14px 18px;
  background: #f6f6f6;
  color: var(--muted-foreground);
  font-size: 11px;
  font-weight: 550;
  white-space: nowrap;
}
.ranking-table th svg {
  display: inline;
  vertical-align: -2px;
}
.ranking-table th:first-child {
  width: 60%;
}
.ranking-table td {
  padding: 17px 18px;
  border-top: 1px solid var(--border);
  vertical-align: middle;
}
.ranking-table tbody > tr:not(.detail-row):hover {
  background: #fcfcfc;
}
.ranking-table .expanded-row {
  background: #f8f9fb;
}
.restaurant-name {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  text-align: left;
  line-height: 1.4;
  font-weight: 560;
}
.restaurant-name:hover {
  color: #005ac4;
}
.restaurant-name svg {
  flex-shrink: 0;
  color: var(--muted-foreground);
}
.chevron-open {
  transform: rotate(90deg);
}
.row-reason {
  margin: 5px 0 0 23px;
  color: var(--muted-foreground);
  font-size: 11px;
  line-height: 1.5;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
.score-cell {
  width: 124px;
}
.score-number {
  font-size: 22px;
  line-height: 1;
  font-weight: 600;
  letter-spacing: -0.04em;
  font-variant-numeric: tabular-nums;
}
.score-track {
  height: 3px;
  width: 70px;
  margin-top: 8px;
  background: #e8e8e8;
  border-radius: 2px;
  overflow: hidden;
}
.score-track > span {
  display: block;
  height: 100%;
  background: var(--foreground);
}
.unscored,
.muted {
  color: var(--muted-foreground);
}
.week-strip {
  display: grid;
  grid-template-columns: repeat(7, 14px);
  gap: 4px;
}
.day-mark {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 2px;
  border: 1px solid #8a8a8a;
  background: #f2f2f2;
  position: relative;
}
.day-mark[data-status="available"] {
  background: #fff;
}
.day-mark[data-status="available"]::after {
  content: "";
  position: absolute;
  inset: 4px;
  border-radius: 100%;
  background: var(--ring);
}
.day-mark[data-status="unavailable"] {
  background: var(--foreground);
  border-color: var(--foreground);
}
.day-mark[data-status="non_service"] {
  background: repeating-linear-gradient(135deg, #bbb 0 1px, #f5f5f5 1px 4px);
}
.day-mark[data-status="unknown"],
.day-mark[data-status="collection_error"],
.day-mark[data-status="missing"],
.day-mark[data-status="unreleased"] {
  background: var(--warn-surface);
  border-color: #b88753;
}
.day-mark[data-status="unknown"]::after,
.day-mark[data-status="collection_error"]::after,
.day-mark[data-status="missing"]::after,
.day-mark[data-status="unreleased"]::after {
  content: "?";
  position: absolute;
  inset: 0;
  text-align: center;
  color: var(--warn);
  font-size: 10px;
  line-height: 12px;
}
.table-footer {
  display: flex;
  justify-content: space-between;
  gap: 10px;
  padding: 14px 0;
  font-size: 11px;
  color: var(--muted-foreground);
}
.empty-table {
  text-align: center;
  color: var(--muted-foreground);
  height: 130px;
}
.ranking-table .detail-row > td {
  padding: 24px 28px 28px;
  background: #f8f9fb;
}
.detail-heading {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  font-size: 12px;
  color: var(--muted-foreground);
}
.detail-heading a {
  display: inline-flex;
  align-items: center;
  gap: 3px;
  color: #005ac4;
}
.detail-heading a:hover {
  text-decoration: underline;
}
.review-reason {
  margin-top: 14px;
  padding: 10px 12px;
  border-left: 2px solid #b88753;
  background: var(--warn-surface);
  color: #713c0d;
  font-size: 13px;
  line-height: 1.6;
}
.detail-grid {
  display: grid;
  grid-template-columns: minmax(250px, 360px) minmax(0, 1fr);
  gap: 44px;
  margin-top: 24px;
}
.calendar-heading {
  margin-bottom: 16px;
  font-size: 13px;
  font-weight: 550;
}
.dinner-calendar {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 6px;
}
.weekday-label {
  text-align: center;
  font-size: 11px;
  color: var(--muted-foreground);
  padding-bottom: 2px;
}
.dinner-calendar button {
  min-height: 35px;
  border-radius: 4px;
  border: 1px solid #8a8a8a;
  background: white;
  font-size: 12px;
  font-variant-numeric: tabular-nums;
}
.dinner-calendar button[data-status="available"] {
  border-bottom: 3px solid #0070f3;
}
.dinner-calendar button[data-status="unavailable"] {
  background: var(--foreground);
  border-color: var(--foreground);
  color: white;
}
.dinner-calendar button[data-status="non_service"] {
  background: repeating-linear-gradient(135deg, #e3e3e3 0 2px, #f5f5f5 2px 6px);
}
.dinner-calendar button[data-status="unknown"],
.dinner-calendar button[data-status="missing"],
.dinner-calendar button[data-status="collection_error"],
.dinner-calendar button[data-status="unreleased"] {
  background: var(--warn-surface);
  color: var(--warn);
  border-style: dashed;
  border-color: #b88753;
}
.dinner-calendar button[aria-pressed="true"] {
  outline: 2px solid var(--ring);
  outline-offset: 2px;
}
.calendar-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 16px;
  margin-top: 15px;
  padding: 0;
  list-style: none;
  font-size: 11px;
  color: var(--muted-foreground);
}
.calendar-legend li {
  display: flex;
  align-items: center;
  gap: 5px;
}
.date-availability h2 {
  font-size: 15px;
  font-weight: 600;
}
.date-availability > p {
  margin-top: 6px;
  font-size: 13px;
  color: var(--muted-foreground);
}
.dinner-times {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin-top: 16px;
  list-style: none;
}
.dinner-times li {
  padding: 6px 10px;
  border: 1px solid var(--border);
  border-radius: 4px;
  background: var(--card);
  font-size: 13px;
  font-variant-numeric: tabular-nums;
}
.retry-button {
  display: block;
  margin-top: 20px;
  padding: 9px 14px;
  background: var(--foreground);
  color: white;
  border-radius: 6px;
}

@media (max-width: 960px) {
  .ranking-table .week-column {
    display: none;
  }
  .detail-grid {
    gap: 28px;
  }
}

@media (max-width: 640px) {
  .ranking-page {
    padding: 30px 16px 48px;
  }
  .scope {
    line-height: 1.8;
    font-size: 12px;
  }
  .scope span {
    padding: 0 3px;
  }
  .snapshot-line {
    gap: 6px;
    flex-direction: column;
  }
  .method {
    margin-bottom: 26px;
  }
  .table-tools {
    align-items: stretch;
    flex-direction: column;
    gap: 12px;
  }
  .status-filters {
    justify-content: space-between;
    gap: 0;
  }
  .status-filters button {
    padding: 8px 10px;
    font-size: 12px;
  }
  .restaurant-search {
    width: 100%;
  }
  .ranking-table th {
    padding: 12px 9px;
    font-size: 10px;
  }
  .ranking-table td {
    padding: 16px 9px;
  }
  .ranking-table th:first-child {
    width: 75%;
  }
  .restaurant-name {
    font-size: 12px;
    gap: 5px;
  }
  .restaurant-name svg {
    width: 12px;
  }
  .score-cell {
    width: 70px;
  }
  .score-number {
    font-size: 20px;
  }
  .score-track {
    width: 42px;
  }
  .row-reason {
    margin-left: 17px;
    font-size: 10px;
  }
  .ranking-table .detail-row > td {
    padding: 18px 12px;
  }
  .detail-grid {
    grid-template-columns: 1fr;
    gap: 24px;
  }
  .table-footer {
    flex-direction: column;
    font-size: 10px;
    line-height: 1.7;
  }
}

import { Fragment, useState } from "react";
import { ArrowDown, ChevronRight, Search } from "lucide-react";

import { formatDay, formatScore, formatSnapshot, statusLabel } from "./format.ts";
import type { RankingData, RestaurantRow } from "./ranking.functions.ts";
import { RestaurantDetail } from "./restaurant-detail.tsx";

type Group = "ranked" | "review" | "excluded";

const groups: { id: Group; label: string }[] = [
  { id: "ranked", label: "Ranked" },
  { id: "review", label: "Needs review" },
  { id: "excluded", label: "Excluded" },
];

function groupOf(restaurant: Pick<RestaurantRow, "eligibility" | "score">): Group {
  if (restaurant.eligibility === "excluded") return "excluded";

  return restaurant.score === null ? "review" : "ranked";
}

function searchText(value: string) {
  return value
    .normalize("NFD")
    .replace(/\p{Diacritic}/gu, "")
    .toLowerCase();
}

export function RankingPage({
  data,
  expandedUrl,
  onToggle,
}: {
  data: RankingData;
  expandedUrl: string | undefined;
  onToggle: (url: string) => void;
}) {
  const [group, setGroup] = useState<Group>(() =>
    data.detail ? groupOf(data.detail.restaurant) : "ranked",
  );

  const [query, setQuery] = useState("");
  const counts: Record<Group, number> = { ranked: 0, review: 0, excluded: 0 };
  let snapshotDate: string | null = null;

  for (const row of data.restaurants) {
    counts[groupOf(row)]++;

    if (!snapshotDate || row.anchorDate > snapshotDate) snapshotDate = row.anchorDate;
  }

  const needle = searchText(query.trim());

  const rows = data.restaurants.filter(
    (row) =>
      groupOf(row) === group && searchText(`${row.name} ${row.address ?? ""}`).includes(needle),
  );

  return (
    <main className="ranking-page">
      <header className="ranking-header">
        <p className="eyebrow">RESY / SAN FRANCISCO</p>
        <h1>Hard-to-book restaurants</h1>
        <p className="scope">
          Party of two <span aria-hidden="true">·</span> Dinner, 6–9 p.m.{" "}
          <span aria-hidden="true">·</span> San Francisco time
        </p>
        <div className="snapshot-line">
          {snapshotDate ? (
            <span>Snapshot: {formatSnapshot(snapshotDate)}</span>
          ) : (
            <span>No data collected yet</span>
          )}
        </div>
        <details className="method">
          <summary>How the score works</summary>
          <div>
            <p>
              <strong>Fewer nights and fewer dinner times available mean a higher score.</strong> We
              compare the next seven days for a party of two. Each distinct start time counts once,
              even if several seating options offer it.
            </p>
            <p>
              Each dinner night contributes 100 points with no opening, or 50 ÷ (1 + available
              times) otherwise: one time gives 25 points; four give 10. The score is the average
              across dinner nights. This gives equal weight to nights without an opening and limited
              time choices.
            </p>
            <p>
              Non-service nights are skipped; unconfirmed dates prevent a score. This is a
              booking-difficulty heuristic, not an occupancy percentage: total tables and occupied
              slots are unknown. Scores approach zero as choices increase; 100 means no openings.
            </p>
          </div>
        </details>
      </header>

      <section aria-label="Restaurant ranking">
        <div className="table-tools">
          <fieldset className="status-filters">
            <legend className="sr-only">Restaurant status</legend>
            {groups.map((item) => (
              <button
                key={item.id}
                type="button"
                aria-pressed={group === item.id}
                aria-label={`${item.label}: ${counts[item.id]} restaurants`}
                onClick={() => setGroup(item.id)}
              >
                {item.label} <span>{counts[item.id]}</span>
              </button>
            ))}
          </fieldset>
          <label className="restaurant-search">
            <Search size={16} aria-hidden="true" />
            <span className="sr-only">Search restaurants</span>
            <input
              type="search"
              placeholder="Search restaurants"
              value={query}
              onChange={(event) => setQuery(event.target.value)}
            />
          </label>
        </div>
        {group === "review" ? (
          <p className="group-note">Not enough verified information to score these restaurants.</p>
        ) : null}
        {group === "excluded" ? (
          <p className="group-note">
            Outside this comparison because of location, service or booking platform.
          </p>
        ) : null}
        <div className="ranking-table-wrap">
          <table className="ranking-table">
            <caption className="sr-only">
              {groups.find((item) => item.id === group)?.label} restaurants. Scored restaurants are
              ordered by scarcity, highest first. Equal scores are ties.
            </caption>
            <thead>
              <tr>
                <th scope="col">Restaurant</th>
                <th scope="col" aria-sort={group === "ranked" ? "descending" : undefined}>
                  Scarcity {group === "ranked" ? <ArrowDown size={12} aria-hidden="true" /> : null}
                </th>
                <th scope="col" className="week-column">
                  Next 7 nights
                </th>
              </tr>
            </thead>
            <tbody>
              {rows.map((restaurant) => {
                const expanded = expandedUrl === restaurant.resyUrl;

                return (
                  <Fragment key={restaurant.resyUrl}>
                    <tr className={expanded ? "expanded-row" : undefined}>
                      <td>
                        <button
                          className="restaurant-name"
                          type="button"
                          aria-expanded={expanded}
                          onClick={() => onToggle(restaurant.resyUrl)}
                        >
                          <ChevronRight
                            size={15}
                            aria-hidden="true"
                            className={expanded ? "chevron-open" : undefined}
                          />
                          <span>{restaurant.name}</span>
                        </button>
                        {group !== "ranked" ? (
                          <p className="row-reason">
                            {restaurant.eligibility === "eligible"
                              ? restaurant.scoreReason
                              : restaurant.eligibilityReason}
                          </p>
                        ) : null}
                      </td>
                      <td className="score-cell">
                        {restaurant.score === null ? (
                          <span className="unscored">
                            <span aria-hidden="true">—</span>
                            <span className="sr-only">Not scored</span>
                          </span>
                        ) : (
                          <>
                            <span className="score-number">{formatScore(restaurant.score)}</span>
                            <div className="score-track" aria-hidden="true">
                              <span style={{ width: `${restaurant.score}%` }} />
                            </div>
                          </>
                        )}
                      </td>
                      <td className="week-column">
                        <div className="week-strip">
                          {restaurant.week.map((day) => (
                            <span
                              key={day.diningDate}
                              className="day-mark"
                              data-status={day.status}
                              title={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                            >
                              <span className="sr-only">
                                {formatDay(day.diningDate)}: {statusLabel[day.status]}
                              </span>
                            </span>
                          ))}
                        </div>
                      </td>
                    </tr>
                    {expanded && data.detail?.restaurant.resyUrl === restaurant.resyUrl ? (
                      <tr className="detail-row">
                        <td colSpan={3}>
                          <RestaurantDetail key={restaurant.resyUrl} detail={data.detail} />
                        </td>
                      </tr>
                    ) : null}
                  </Fragment>
                );
              })}
              {rows.length === 0 ? (
                <tr>
                  <td colSpan={3} className="empty-table">
                    {query
                      ? "No matching restaurants in this group. Try another name or status."
                      : "No restaurants in this group yet."}
                  </td>
                </tr>
              ) : null}
            </tbody>
          </table>
        </div>
        <footer className="table-footer">
          <span>
            {rows.length} restaurant{rows.length === 1 ? "" : "s"}
            {query ? " matching" : " shown"}
          </span>
        </footer>
      </section>
    </main>
  );
}

import { useState } from "react";
import { ArrowUpRight } from "lucide-react";

import { addDays } from "../scarcity/model.ts";
import { formatDay, formatDinnerTime, formatWeekday, statusLabel } from "./format.ts";
import type { DayStatus } from "./format.ts";
import type { RestaurantDetailData } from "./ranking.functions.ts";

export function RestaurantDetail({ detail }: { detail: RestaurantDetailData }) {
  const { restaurant, observations } = detail;
  const [selectedDate, setSelectedDate] = useState(addDays(restaurant.anchorDate, 1));
  const byDate = new Map(observations.map((observation) => [observation.diningDate, observation]));

  const days = Array.from({ length: 28 }, (_, index) => {
    const diningDate = addDays(restaurant.anchorDate, index + 1);
    const status: DayStatus = byDate.get(diningDate)?.status ?? "missing";

    return { diningDate, status };
  });

  const selected = byDate.get(selectedDate);
  const selectedStatus = selected?.status ?? "missing";
  const showCalendar = restaurant.eligibility !== "excluded" && observations.length > 0;

  return (
    <article className="restaurant-detail" aria-label={`${restaurant.name} availability`}>
      <header className="detail-heading">
        <p>{restaurant.address ?? "Address not verified"}</p>
        <a href={restaurant.resyUrl} target="_blank" rel="noreferrer">
          Open on Resy <ArrowUpRight size={14} aria-hidden="true" />
        </a>
      </header>
      {restaurant.score === null ? (
        <p className="review-reason">
          {restaurant.eligibility === "eligible"
            ? restaurant.scoreReason
            : restaurant.eligibilityReason}
        </p>
      ) : null}
      {showCalendar ? (
        <div className="detail-grid">
          <section aria-label="Dinner availability by date">
            <h2 className="calendar-heading">
              {formatDay(days[0].diningDate)} – {formatDay(days[27].diningDate)}
            </h2>
            <div className="dinner-calendar">
              {days.slice(0, 7).map((day) => (
                <span className="weekday-label" key={day.diningDate}>
                  {formatWeekday(day.diningDate)}
                </span>
              ))}
              {days.map((day) => (
                <button
                  key={day.diningDate}
                  type="button"
                  data-status={day.status}
                  aria-pressed={day.diningDate === selectedDate}
                  aria-label={`${formatDay(day.diningDate)}: ${statusLabel[day.status]}`}
                  onClick={() => setSelectedDate(day.diningDate)}
                >
                  {Number(day.diningDate.slice(-2))}
                </button>
              ))}
            </div>
            <ul className="calendar-legend">
              <li>
                <span className="day-mark" data-status="available" />
                Available
              </li>
              <li>
                <span className="day-mark" data-status="unavailable" />
                No opening
              </li>
              <li>
                <span className="day-mark" data-status="non_service" />
                No service
              </li>
              <li>
                <span className="day-mark" data-status="unknown" />
                Unconfirmed
              </li>
            </ul>
          </section>
          <section className="date-availability" aria-live="polite">
            <h2>{formatDay(selectedDate)}</h2>
            {selected?.status === "available" ? (
              <>
                <p>
                  {selected.times.length} dinner time{selected.times.length === 1 ? "" : "s"}{" "}
