  --background: #fafafa;
  --foreground: #171717;
  --card: #ffffff;
  --muted: #f3f3f3;
  --muted-foreground: #626262;
  --border: #e5e5e5;
  --ring: #0070f3;
  --warn: #92400e;
  --warn-surface: #fff8ed;
}

@theme inline {
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-border: var(--border);
  --color-ring: var(--ring);
}

@layer base {
  * {
    border-color: var(--border);
  }
  body {
    margin: 0;
    background: var(--background);
    color: var(--foreground);
    font-family: var(--font-sans);
    -webkit-font-smoothing: antialiased;
  }
  button,
  input,
  summary {
    font: inherit;
  }
  button,
  summary {
    cursor: pointer;
  }
  button {
    color: inherit;
  }
  a {
    text-underline-offset: 3px;
  }
  :focus-visible {
    outline: 2px solid var(--ring);
    outline-offset: 4px;
  }
}

.ranking-page {
  max-width: 1160px;
  margin: 0 auto;
  padding: 56px 32px 80px;
}
.eyebrow {
  font-size: 11px;
  letter-spacing: 0.15em;
  font-weight: 650;
  color: var(--muted-foreground);
}
.ranking-header h1 {
  margin: 14px 0 12px;
  font-size: clamp(30px, 4vw, 44px);
  font-weight: 620;
  line-height: 1.1;
  letter-spacing: -0.045em;
}
.scope {
  font-size: 14px;
  color: var(--muted-foreground);
}
.scope span {
  padding: 0 7px;
}
.snapshot-line {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 20px;
  margin-top: 18px;
  font-size: 12px;
  color: var(--muted-foreground);
}
.method {
  margin: 18px 0 34px;
  font-size: 13px;
}
.method summary {
  width: fit-content;
  color: var(--muted-foreground);
}
.method > div {
  max-width: 760px;
  padding: 8px 0 2px;
  color: var(--muted-foreground);
  line-height: 1.7;
}
.method p + p {
  margin-top: 10px;
}
.method strong {
  font-weight: 600;
  color: var(--foreground);
}
.table-tools {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.status-filters {
  display: flex;
  align-items: center;
  gap: 4px;
}
.status-filters button {
  border-radius: 6px;
  padding: 8px 12px;
  font-size: 13px;
  color: var(--muted-foreground);
}
.status-filters button:hover {
  background: var(--muted);
}
.status-filters button[aria-pressed="true"] {
  background: var(--foreground);
  color: white;
}
.status-filters button span {
