}
.week-strip {
  display: grid;
  grid-template-columns: repeat(7, 14px);
  gap: 4px;
}
.day-mark {
  display: inline-block;
  width: 14px;
  height: 14px;
  border-radius: 2px;
  border: 1px solid #8a8a8a;
