content.text:
@import "tailwindcss";
@import "tw-animate-css";

:root {
  color-scheme: light;
  --background: #fafafa;
  --foreground: #171717;
  --card: #ffffff;
  --card-foreground: var(--foreground);
  --popover: var(--card);
  --popover-foreground: var(--foreground);
  --primary: var(--foreground);
  --primary-foreground: var(--card);
  --secondary: #f3f3f3;
  --secondary-foreground: var(--foreground);
  --muted: #f6f6f6;
  --muted-foreground: #626262;
  --accent: #f8f9fb;
  --accent-foreground: var(--foreground);
  --destructive: #b91c1c;
  --destructive-foreground: var(--card);
  --border: #e5e5e5;
  --input: #8a8a8a;
  --ring: #0070f3;
  --link: #005ac4;
  --available: #0070f3;
  --track: #e8e8e8;
  --warning: #fff8ed;
  --warning-foreground: #92400e;
  --warning-emphasis: #713c0d;
  --warning-border: #b88753;
}

@theme inline {
  --font-sans: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --radius-lg: 0.625rem;
  --color-background: var(--background);
  --color-foreground: var(--foreground);
  --color-card: var(--card);
  --color-card-foreground: var(--card-foreground);
  --color-popover: var(--popover);
  --color-popover-foreground: var(--popover-foreground);
  --color-primary: var(--primary);
  --color-primary-foreground: var(--primary-foreground);
  --color-secondary: var(--secondary);
  --color-secondary-foreground: var(--secondary-foreground);
  --color-muted: var(--muted);
  --color-muted-foreground: var(--muted-foreground);
  --color-accent: var(--accent);
  --color-accent-foreground: var(--accent-foreground);
  --color-destructive: var(--destructive);
  --color-destructive-foreground: var(--destructive-foreground);
  --color-border: var(--border);
  --color-input: var(--input);
  --color-ring: var(--ring);
  --color-link: var(--link);
  --color-available: var(--available);
  --color-track: var(--track);
  --color-warning: var(--warning);
  --color-warning-foreground: var(--warning-foreground);
  --color-warning-emphasis: var(--warning-emphasis);
  --color-warning-border: var(--warning-border);
}

/* Preserve the UI's inclusive breakpoints, including at exactly 640px and 960px. */
@custom-variant tablet (@media (max-width: 960px));
@custom-variant mobile (@media (max-width: 640px));

@layer base {
  * {
    @apply border-border;
  }

  body {
    @apply bg-background font-sans text-foreground antialiased;
  }

  button,
  summary {
    @apply cursor-pointer;
  }

  a {
    @apply underline-offset-3;
  }

  :focus-visible {
    @apply outline-2 outline-offset-4 outline-ring;
  }
}

/* Decorative hatching has no semantic palette role of its own. Keep its two
   densities here rather than introducing tokens for individual stripe colors. */
@utility bg-non-service {
  background-image: repeating-linear-gradient(135deg, #e3e3e3 0 2px, #f5f5f5 2px 6px);
}

@utility bg-non-service-mark {
  background-image: repeating-linear-gradient(135deg, #bbb 0 1px, #f5f5f5 1px 4px);
}

import { cva } from "class-variance-authority";

import type { DayStatus } from "./format.ts";

const appearanceByStatus = {
  available: "available",
  unavailable: "unavailable",
  non_service: "non-service",
  unknown: "unconfirmed",
  collection_error: "unconfirmed",
  missing: "unconfirmed",
  unreleased: "unconfirmed",
} as const satisfies Record<DayStatus, string>;

const dayVariants = cva("border", {
  variants: {
    appearance: {
      available: "border-input bg-card",
      unavailable: "border-primary bg-primary text-primary-foreground",
      "non-service": "border-input",
      unconfirmed: "border-warning-border bg-warning text-warning-foreground",
    },
    kind: {
      marker: "relative inline-block size-3.5 rounded-xs",
      calendar:
        "min-h-8.75 rounded-sm text-xs/normal tabular-nums aria-pressed:outline-2 aria-pressed:outline-offset-2 aria-pressed:outline-ring",
    },
  },
  compoundVariants: [
    {
      appearance: "available",
      kind: "marker",
      class:
        "after:absolute after:inset-1 after:rounded-full after:bg-available after:content-['']",
    },
    {
      appearance: "available",
      kind: "calendar",
      class: "border-b-3 border-b-available",
    },
    { appearance: "non-service", kind: "marker", class: "bg-non-service-mark" },
    { appearance: "non-service", kind: "calendar", class: "bg-non-service" },
    {
      appearance: "unconfirmed",
      kind: "marker",
      class:
        "after:absolute after:inset-0 after:text-center after:text-[10px]/3 after:content-['?']",
    },
    { appearance: "unconfirmed", kind: "calendar", class: "border-dashed" },
  ],
});

export function availabilityDayClasses(status: DayStatus, kind: "marker" | "calendar") {
  return dayVariants({ appearance: appearanceByStatus[status], kind });
}

export function DayMark({ status, label }: { status: DayStatus; label?: string }) {
  return (
    <span className={availabilityDayClasses(status, "marker")} data-status={status} title={label}>
      {label ? <span className="sr-only">{label}</span> : null}
    </span>
  );
}
